import{_ as e,o as r,c as o,ai as t}from"./chunks/framework.CyVd0iGZ.js";const y=JSON.parse('{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy/index.md","filePath":"privacy/index.md"}'),i={name:"privacy/index.md"};function n(s,a,l,c,d,p){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p>Last updated: May 11, 2026</p><p>Field Report Pro is a paid iOS app for creating field inspection and photo PDF reports.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><ul><li>Field Report Pro does not require an account.</li><li>Field Report Pro does not operate a backend server for customer report storage.</li><li>Report data and attached photos are stored locally on your device.</li><li>The app does not sell personal data.</li><li>Data leaves your device only when you choose to export or share a report through iOS.</li></ul><h2 id="information-we-access" tabindex="-1">Information We Access <a class="header-anchor" href="#information-we-access" aria-label="Permalink to “Information We Access”">​</a></h2><p>Field Report Pro may request access to:</p><ul><li>Camera: so you can take jobsite photos and attach them to a report.</li><li>Photo Library: so you can import existing photos into a report.</li></ul><p>This access is used only to support core app features.</p><h2 id="how-data-is-stored" tabindex="-1">How Data Is Stored <a class="header-anchor" href="#how-data-is-stored" aria-label="Permalink to “How Data Is Stored”">​</a></h2><p>Report information such as client name, address, notes, issue details, and photos is stored locally using Apple system storage on your device.</p><p>The developer does not automatically collect, sync, or back up this report content to an external server.</p><h2 id="sharing-and-export" tabindex="-1">Sharing and Export <a class="header-anchor" href="#sharing-and-export" aria-label="Permalink to “Sharing and Export”">​</a></h2><p>When you export a PDF or share content using the iOS share sheet, the destination is chosen by you. Once you send a file to Mail, Files, AirDrop, Messages, or another app or service, that destination’s own privacy practices apply.</p><h2 id="analytics-and-tracking" tabindex="-1">Analytics and Tracking <a class="header-anchor" href="#analytics-and-tracking" aria-label="Permalink to “Analytics and Tracking”">​</a></h2><p>Field Report Pro does not include third-party advertising SDKs and does not use cross-app tracking for advertising purposes.</p><p>If analytics or crash reporting tools are added in a future release, this policy and the App Store privacy disclosure will be updated before release.</p><h2 id="data-retention" tabindex="-1">Data Retention <a class="header-anchor" href="#data-retention" aria-label="Permalink to “Data Retention”">​</a></h2><p>Because report data is stored locally, you control retention by editing or deleting reports from the app and by managing the app’s data on your device.</p><h2 id="children-s-privacy" tabindex="-1">Children’s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to “Children’s Privacy”">​</a></h2><p>Field Report Pro is not directed to children.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to “Contact”">​</a></h2><p>Support contact:</p><ul><li>Support email: <code>lidonghui11911@gmail.com</code></li></ul>',24)])])}const u=e(i,[["render",n]]);export{y as __pageData,u as default};
